{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LONG_TAIL_MASTER_BIBLE as with a2 as ( select LEFT(sku,12) as sku2, count(marketplace) as online_free, count(case when order_date >= current_date - 30 then marketplace else null end ) as online_free_l30 from snitch_db.maplemonk.unicommerce_fact_items_intermediate where sku_group like \'%4MSFR%\' and selling_price < 30 and marketplace_mapped in (\'SHOPIFY\') group by 1 ), a1 as ( select LEFT(sku,12) as sku_group , count(marketplace) as offline_free, count(case when order_date >= current_date - 30 then marketplace else null end ) as offline_free_l30 from snitch_db.maplemonk.store_fact_items_offline where sku_group like \'%4MSFR%\' and selling_price < 10 group by 1 ), freegift as ( select coalesce(sku2,sku_group) as sku_group, online_free, offline_free, online_free_l30, offline_free_l30, (online_free + offline_free) as total_free, (online_free_l30 + offline_free_l30) as total_free_l30 from a2 o left join a1 f on o.sku2 = f.sku_group ), bible as ( select * from snitch_db.maplemonk.sku_master_v1 where sku_group like \'%4MSFR%\' ) select B.*, F.online_free, f.offline_free, f.offline_free_l30, f.online_free_l30, f.total_free, f.total_free_l30 from bible b left join freegift f on f.sku_group = b.sku_group ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.MTD_TARGET_perfumes as SELECT COALESCE(TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\')) AS date, TRIM(\"Branch \") AS branch_code, ( REPLACE(\"Target \", \',\', \'\')::INT) * 0.03 AS target, ( REPLACE(\"MTD \", \',\', \'\')::INT) * 0.03 AS mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.MTD_TARGET_shoes as SELECT COALESCE(TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\')) AS date, TRIM(\"Branch \") AS branch_code, ( REPLACE(\"Target \", \',\', \'\')::INT) * 0.02 AS target, ( REPLACE(\"MTD \", \',\', \'\')::INT) * 0.02 AS mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.long_tail_dsr_perfumes as WITH sales_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS MRP_sales, sum(cogs_price*shipping_quantity) as cogs_sales, SUM(selling_price) AS gross_sales, COUNT(DISTINCT ORDER_NAME) AS bills, SUM(SUBORDER_QUANTITY) AS qty FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'NT%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'%4MSFR%\' GROUP BY 1, 2 ), returns_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS mrp_returns, sum(cogs_price*shipping_quantity) as cogs_returns, SUM(selling_price) AS ret_sales, SUM(SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND SKU_GROUP NOT LIKE \'NT%\' and order_name not like \'RTO%\' and sku_group like \'%4MSFR%\' GROUP BY 1, 2 ), multies_daily AS ( SELECT date, branch_code, COUNT(DISTINCT order_id) AS multies FROM ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, order_id, SUM(SHIPPING_QUANTITY) AS q FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE sku_group NOT LIKE \'CB%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'%4MSFR%\' GROUP BY 1, 2, 3 ) WHERE q >= 2 GROUP BY 1, 2 ), omni_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(shipping_quantity) as omni_sales_qty, SUM(selling_price) AS omni_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND DOC_PREFIX IN (\'OMS\') and sku_group like \'%4MSFR%\' GROUP BY 1, 2 ), walkins_daily AS ( SELECT DATE_TRUNC(\'day\', order_date::DATE) AS date, round(code,0) AS branch_code, SUM(walk_ins) AS walk_ins FROM SNITCH_DB.MAPLEMONK.OFFLINE_WALKINS GROUP BY 1, 2 ), targets AS ( SELECT date, branch_code, target, mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET_perfumes ), mapping AS ( SELECT branch_code, marketplace_mapped FROM ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY DATE_TRUNC(\'day\', ORDER_TIMESTAMP) DESC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE ) WHERE rn = 1 ), net_daily AS ( SELECT s.date, s.branch_code, YEAR(s.date) AS yr, MONTH(s.date) AS mth, DAY(s.date) AS dom, s.gross_sales - COALESCE(r.ret_sales, 0) AS net_sales, s.MRP_sales - COALESCE(r.mrp_returns, 0) AS net_mrp, s.cogs_sales - COALESCE(r.cogs_returns, 0) as net_cogs, s.bills, s.qty - COALESCE(r.ret_qty, 0) AS net_qty, COALESCE(m.multies, 0) AS multies, COALESCE(o.omni_sales, 0) AS omni_sales, coalesce(o.omni_sales_qty,0) as omni_sales_qty, COALESCE(wk.walk_ins, 0) AS walk_ins FROM sales_daily s LEFT JOIN returns_daily r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) LEFT JOIN multies_daily m ON m.date = s.date AND LOWER(m.branch_code) = LOWER(s.branch_code) LEFT JOIN omni_daily o ON o.date = s.date AND LOWER(o.branch_code) = LOWER(s.branch_code) LEFT JOIN walkins_daily wk ON wk.date = s.date AND LOWER(wk.branch_code) = LOWER(s.branch_code) ), enriched AS ( SELECT nd.*, SUM(net_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_sales, SUM(bills) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_bills, SUM(net_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_qty, SUM(omni_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni, SUM(omni_sales_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni_qty, SUM(walk_ins) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_walkins, SUM(net_mrp) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_mrp, SUM(net_cogs) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) as mtd_cogs FROM net_daily nd ), inv_raw AS ( SELECT date, branch_code, base_stock, cluster, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, fresh_inventory, new_category, COALESCE(NULLIF(dept_ideal, 0), 12) AS depth, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS, JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(sku_group) LIKE \'SH0%\' THEN CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN CASE WHEN ( (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END)) < 3 AND ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END)) < 4 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE INVENTORY + JIT_QTY > 0 and sku_group like \'%4MSFR%\' ), inv_bucketed AS ( SELECT date, branch_code, cluster, sku_group, closing_inventory, fresh_inventory, cut_size, new_category, base_stock, depth, CASE WHEN UPPER(new_category) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\',\'LUGGAGE\') THEN \'Long_Tail\' WHEN new_category IS NULL THEN NULL ELSE \'Apparel\' END AS category_bucket FROM inv_raw ), inv_agg AS ( SELECT date, branch_code, MAX(base_stock) AS base_stock, MAX(depth) AS depth, SUM(closing_inventory) AS total_inv, SUM(fresh_inventory) AS fresh_inv, SUM(CASE WHEN category_bucket = \'Apparel\' THEN closing_inventory END) AS apparel_inv, COUNT(DISTINCT CASE WHEN category_bucket = \'Apparel\' THEN sku_group END) AS total_options, COUNT(DISTINCT CASE WHEN cut_size = \'YES\' AND category_bucket = \'Apparel\' THEN sku_group END) AS cut_options, COUNT(DISTINCT CASE WHEN cut_size = \'NO\' AND category_bucket = \'Apparel\' THEN sku_group END) AS full_options FROM inv_bucketed WHERE category_bucket IS NOT NULL AND branch_code IS NOT NULL GROUP BY date, branch_code ), inv_metrics AS ( SELECT date, branch_code, COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ) AS base_stock, ROUND(DIV0( COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ), depth )) AS ideal_options, COALESCE(total_inv, 0) AS total_inv, COALESCE(fresh_inv, 0) AS fresh_inv, COALESCE(apparel_inv, 0) AS apparel_inv, COALESCE(total_options, 0) AS total_options, COALESCE(cut_options, 0) AS cut_options, COALESCE(full_options, 0) AS full_options FROM inv_agg ), cust_first AS ( SELECT phone_no, MIN(first_order_date) AS first_order_date FROM SNITCH_DB.MAPLEMONK.CUSTOMER_ACQ_DATE_CHANNEL GROUP BY phone_no ), seg_sales AS ( SELECT DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) AS date, f.branch_code, CASE WHEN DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, COUNT(DISTINCT f.ORDER_NAME) AS bills, SUM(f.selling_price) AS gross_sales, SUM(f.mrp * f.shipping_quantity) AS mrp_gross, SUM(f.SUBORDER_QUANTITY) AS qty_gross FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE f LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) WHERE f.ORDER_STATUS = \'Processed\' AND f.sku_group NOT LIKE \'CB%\' AND f.sku_group NOT LIKE \'NT%\' AND f.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') GROUP BY 1, 2, 3 ), seg_returns AS ( SELECT DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) AS date, r.branch_code, CASE WHEN DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, SUM(r.selling_price) AS ret_sales, SUM(r.mrp * r.shipping_quantity) AS mrp_ret, SUM(r.SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS r LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(r.phone, \'[^0-9]\', \'\'), 10) WHERE r.ORDER_STATUS = \'Processed\' AND r.category <> \'CARRY BAG\' GROUP BY 1, 2, 3 ), seg_net AS ( SELECT COALESCE(s.date, r.date) AS date, COALESCE(s.branch_code, r.branch_code) AS branch_code, COALESCE(s.seg, r.seg) AS seg, COALESCE(s.bills, 0) AS bills, COALESCE(s.gross_sales, 0) - COALESCE(r.ret_sales, 0) AS net_sales, COALESCE(s.mrp_gross, 0) - COALESCE(r.mrp_ret, 0) AS net_mrp, COALESCE(s.qty_gross, 0) - COALESCE(r.ret_qty, 0) AS net_qty, coalesce(s.gross_sales,0) as gross_sales, coalesce(r.ret_sales,0) as gross_returns FROM seg_sales s FULL OUTER JOIN seg_returns r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) AND r.seg = s.seg ), seg_daily AS ( SELECT date, branch_code, SUM(CASE WHEN seg = \'new\' THEN bills END) AS new_bills, SUM(CASE WHEN seg = \'new\' THEN net_sales END) AS new_sales, SUM(CASE WHEN seg = \'new\' THEN net_qty END) AS new_qty, SUM(CASE WHEN seg = \'new\' THEN net_mrp END) AS new_mrp, SUM(CASE WHEN seg = \'repeat\' THEN bills END) AS rpt_bills, SUM(CASE WHEN seg = \'repeat\' THEN net_sales END) AS rpt_sales, SUM(CASE WHEN seg = \'repeat\' THEN net_qty END) AS rpt_qty, SUM(CASE WHEN seg = \'repeat\' THEN net_mrp END) AS rpt_mrp FROM seg_net GROUP BY 1, 2 ), store_classification as ( select branch_code,location_simp,type_simp,city from snitch_db.maplemonk.offline_store_classification ) SELECT DATE_TRUNC(\'month\', e.date) AS month, e.date, e.branch_code, map.marketplace_mapped AS store_name, TRIM(SPLIT_PART(map.marketplace_mapped, \'-\', 2)) AS operating_model, UPPER(mo.STATE) AS STATE, mo.REGION, CASE WHEN UPPER(mo.PARTNER) IN (\'ABACUS AGENCIES INDIA PRIVATE LIMITED\') THEN \'ABACUS AGENCIES\' WHEN UPPER(mo.PARTNER) IN (\'KJ FASHION\') THEN \'KJ FASHION\' WHEN UPPER(mo.PARTNER) IN (\'SHIVERA LIFESTYLE\', \'SHIVERA LIFESTYLES PRIVATE LIMITED\') THEN \'DREAM SHIVERA PRIVATE LIMITED\' WHEN UPPER(mo.PARTNER) IN (\'SAPL\', \'SNITCH APPAREL PVT. LTD.\', \'SNITCH APPARELS PVT LTD\') THEN \'COCO\' ELSE UPPER(mo.PARTNER) END AS partner, UPPER(mo.AM) AS AM, mo.RM, mo.NSM, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' WHEN UPPER(mo.STATE) IN (\'ASSAM\',\'BIHAR\',\'CHHATTISGARH\',\'ODHISSA\',\'PUNJAB\',\'RAJASTHAN\',\'WEST BENGAL\') THEN \'ANISHA\' WHEN UPPER(mo.STATE) IN (\'KARNATAKA\') THEN \'PRIYANKA\' WHEN UPPER(mo.STATE) IN (\'MAHARASHTRA\') THEN \'RASHMI\' WHEN UPPER(mo.STATE) IN (\'NEW DELHI\',\'HARYANA\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'YUVRAJ\' WHEN UPPER(mo.STATE) IN (\'ANDHRA PRADESH\',\'TELANGANA\') THEN \'PREKSHYA\' WHEN UPPER(mo.STATE) IN (\'GUJARAT\',\'MADHYA PRADESH\') THEN \'APARNA\' WHEN UPPER(mo.STATE) IN (\'KERALA\',\'TAMIL NADU\') THEN \'P RAWAT\' ELSE \'UNKNOWN\' END AS MERCH_POC, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' ELSE \'FRESH\' END AS STORE_STATUS, UPPER(SC.CITY) AS CITY, sc.location_simp as CITY_TYPE, sc.type_simp as LOCATION_TYPE, t.target, e.net_sales AS sales, DIV0(e.net_sales, t.target) AS ach_pct, DIV0(e.net_sales - w.net_sales, w.net_sales) AS wow_growth_pct, t.mtd_target, e.mtd_sales, DIV0(e.mtd_sales, t.mtd_target) AS mtd_ach_pct, e.mtd_sales AS mtd_sales_net, e.bills, e.net_qty AS qty, e.multies, e.net_mrp AS mrp_sales, e.mtd_mrp AS mrp_sales_mtd, e.net_cogs AS cogs_sales, e.mtd_cogs AS cogs_sales_mtd, DIV0(e.net_mrp - e.net_sales, e.net_mrp) AS disc_pct, DIV0(e.mtd_mrp - e.mtd_sales, e.mtd_mrp) AS disc_pct_mtd, DIV0(e.net_qty, e.bills) AS upt_today, DIV0(e.mtd_qty, e.mtd_bills) AS upt_mtd, DIV0(e.net_sales, e.bills) AS atv_today, DIV0(e.mtd_sales, e.mtd_bills) AS atv_mtd, DIV0(e.net_sales, e.net_qty) AS asp, sg.new_sales AS new_sales, sg.rpt_sales AS repeat_sales, sg.new_bills AS new_bills, sg.rpt_bills AS repeat_bills, sg.new_qty AS new_qty, sg.rpt_qty AS repeat_qty, sg.new_mrp AS new_mrp, sg.rpt_mrp AS repeat_mrp, DIV0(sg.new_qty, sg.new_bills) AS new_upt, DIV0(sg.rpt_qty, sg.rpt_bills) AS repeat_upt, DIV0(sg.new_sales, sg.new_bills) AS new_aov, DIV0(sg.rpt_sales, sg.rpt_bills) AS repeat_aov, DIV0(sg.new_mrp - sg.new_sales, sg.new_mrp) AS new_disc_pct, DIV0(sg.rpt_mrp - sg.rpt_sales, sg.rpt_mrp) AS repeat_disc_pct, ly.mtd_sales AS l2l_sales_25, e.mtd_sales AS l2l_sales_26, DIV0(e.mtd_sales - ly.mtd_sales, ly.mtd_sales) AS l2l_growth_pct, e.omni_sales AS omni_sales, e.mtd_omni AS omni_sales_mtd, e.omni_sales_qty AS omni_sales_qty, e.mtd_omni_qty AS omni_sales_qty_mtd, e.walk_ins AS footfall_today, e.mtd_walkins AS footfall_mtd, DIV0(e.bills, e.walk_ins) AS conversion_today, DIV0(e.mtd_bills, e.mtd_walkins) AS conversion_mtd, DIV0(e.walk_ins - w.walk_ins, w.walk_ins) AS ff_growth_pct, iv.base_stock, iv.ideal_options, iv.total_inv AS inv_total, iv.apparel_inv AS inv_apparel, iv.fresh_inv AS inv_fresh, iv.total_options, iv.cut_options, iv.full_options, FROM enriched e LEFT JOIN mapping map ON LOWER(map.branch_code) = LOWER(e.branch_code) LEFT JOIN SNITCH_DB.MAPLEMONK.MASTER_OFFINE mo ON TRIM(e.branch_code) = TRIM(mo.\"BRANCH CODE\") LEFT JOIN targets t ON t.date = e.date AND LOWER(t.branch_code) = LOWER(e.branch_code) LEFT JOIN enriched w ON w.branch_code = e.branch_code AND w.date = DATEADD(\'day\', -7, e.date) LEFT JOIN enriched ly ON ly.branch_code = e.branch_code AND ly.yr = e.yr - 1 AND ly.mth = e.mth AND ly.dom = e.dom LEFT JOIN inv_metrics iv ON iv.date = e.date AND LOWER(iv.branch_code) = LOWER(e.branch_code) LEFT JOIN seg_daily sg ON sg.date = e.date AND LOWER(sg.branch_code) = LOWER(e.branch_code) LEFT JOIN store_classification sc on LOWER(sc.branch_code) = LOWER(e.branch_code) WHERE map.marketplace_mapped NOT LIKE \'%- WH -%\' and map.marketplace_mapped NOT IN (\'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - SNITCH X\',\'SNITCH - FOCO - MAPLE MYSURU\') ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.long_tail_dsr_shoes as WITH sales_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS MRP_sales, sum(cogs_price*shipping_quantity) as cogs_sales, SUM(selling_price) AS gross_sales, COUNT(DISTINCT ORDER_NAME) AS bills, SUM(SUBORDER_QUANTITY) AS qty FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'NT%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'SH%\' GROUP BY 1, 2 ), returns_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(mrp*shipping_quantity) AS mrp_returns, sum(cogs_price*shipping_quantity) as cogs_returns, SUM(selling_price) AS ret_sales, SUM(SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND SKU_GROUP NOT LIKE \'NT%\' and order_name not like \'RTO%\' and sku_group like \'SH%\' GROUP BY 1, 2 ), multies_daily AS ( SELECT date, branch_code, COUNT(DISTINCT order_id) AS multies FROM ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, order_id, SUM(SHIPPING_QUANTITY) AS q FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE sku_group NOT LIKE \'CB%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and sku_group like \'SH%\' GROUP BY 1, 2, 3 ) WHERE q >= 2 GROUP BY 1, 2 ), omni_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(shipping_quantity) as omni_sales_qty, SUM(selling_price) AS omni_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND DOC_PREFIX IN (\'OMS\') and sku_group like \'SH%\' GROUP BY 1, 2 ), walkins_daily AS ( SELECT DATE_TRUNC(\'day\', order_date::DATE) AS date, round(code,0) AS branch_code, SUM(walk_ins) AS walk_ins FROM SNITCH_DB.MAPLEMONK.OFFLINE_WALKINS GROUP BY 1, 2 ), targets AS ( SELECT date, branch_code, target, mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET_shoes ), mapping AS ( SELECT branch_code, marketplace_mapped FROM ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY DATE_TRUNC(\'day\', ORDER_TIMESTAMP) DESC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE ) WHERE rn = 1 ), net_daily AS ( SELECT s.date, s.branch_code, YEAR(s.date) AS yr, MONTH(s.date) AS mth, DAY(s.date) AS dom, s.gross_sales - COALESCE(r.ret_sales, 0) AS net_sales, s.MRP_sales - COALESCE(r.mrp_returns, 0) AS net_mrp, s.cogs_sales - COALESCE(r.cogs_returns, 0) as net_cogs, s.bills, s.qty - COALESCE(r.ret_qty, 0) AS net_qty, COALESCE(m.multies, 0) AS multies, COALESCE(o.omni_sales, 0) AS omni_sales, coalesce(o.omni_sales_qty,0) as omni_sales_qty, COALESCE(wk.walk_ins, 0) AS walk_ins FROM sales_daily s LEFT JOIN returns_daily r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) LEFT JOIN multies_daily m ON m.date = s.date AND LOWER(m.branch_code) = LOWER(s.branch_code) LEFT JOIN omni_daily o ON o.date = s.date AND LOWER(o.branch_code) = LOWER(s.branch_code) LEFT JOIN walkins_daily wk ON wk.date = s.date AND LOWER(wk.branch_code) = LOWER(s.branch_code) ), enriched AS ( SELECT nd.*, SUM(net_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_sales, SUM(bills) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_bills, SUM(net_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_qty, SUM(omni_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni, SUM(omni_sales_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni_qty, SUM(walk_ins) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_walkins, SUM(net_mrp) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_mrp, SUM(net_cogs) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) as mtd_cogs FROM net_daily nd ), inv_raw AS ( SELECT date, branch_code, base_stock, cluster, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, fresh_inventory, new_category, COALESCE(NULLIF(dept_ideal, 0), 12) AS depth, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS, JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(sku_group) LIKE \'SH0%\' THEN CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN CASE WHEN ( (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END)) < 3 AND ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END)) < 4 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE INVENTORY + JIT_QTY > 0 and sku_group like \'SH%\' ), inv_bucketed AS ( SELECT date, branch_code, cluster, sku_group, closing_inventory, fresh_inventory, cut_size, new_category, base_stock, depth, CASE WHEN UPPER(new_category) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\',\'LUGGAGE\') THEN \'Long_Tail\' WHEN new_category IS NULL THEN NULL ELSE \'Apparel\' END AS category_bucket FROM inv_raw ), inv_agg AS ( SELECT date, branch_code, MAX(base_stock) AS base_stock, MAX(depth) AS depth, SUM(closing_inventory) AS total_inv, SUM(fresh_inventory) AS fresh_inv, SUM(CASE WHEN category_bucket = \'Apparel\' THEN closing_inventory END) AS apparel_inv, COUNT(DISTINCT CASE WHEN category_bucket = \'Apparel\' THEN sku_group END) AS total_options, COUNT(DISTINCT CASE WHEN cut_size = \'YES\' AND category_bucket = \'Apparel\' THEN sku_group END) AS cut_options, COUNT(DISTINCT CASE WHEN cut_size = \'NO\' AND category_bucket = \'Apparel\' THEN sku_group END) AS full_options FROM inv_bucketed WHERE category_bucket IS NOT NULL AND branch_code IS NOT NULL GROUP BY date, branch_code ), inv_metrics AS ( SELECT date, branch_code, COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ) AS base_stock, ROUND(DIV0( COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ), depth )) AS ideal_options, COALESCE(total_inv, 0) AS total_inv, COALESCE(fresh_inv, 0) AS fresh_inv, COALESCE(apparel_inv, 0) AS apparel_inv, COALESCE(total_options, 0) AS total_options, COALESCE(cut_options, 0) AS cut_options, COALESCE(full_options, 0) AS full_options FROM inv_agg ), cust_first AS ( SELECT phone_no, MIN(first_order_date) AS first_order_date FROM SNITCH_DB.MAPLEMONK.CUSTOMER_ACQ_DATE_CHANNEL GROUP BY phone_no ), seg_sales AS ( SELECT DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) AS date, f.branch_code, CASE WHEN DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, COUNT(DISTINCT f.ORDER_NAME) AS bills, SUM(f.selling_price) AS gross_sales, SUM(f.mrp * f.shipping_quantity) AS mrp_gross, SUM(f.SUBORDER_QUANTITY) AS qty_gross FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE f LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) WHERE f.ORDER_STATUS = \'Processed\' AND f.sku_group NOT LIKE \'CB%\' AND f.sku_group NOT LIKE \'NT%\' AND f.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') GROUP BY 1, 2, 3 ), seg_returns AS ( SELECT DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) AS date, r.branch_code, CASE WHEN DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, SUM(r.selling_price) AS ret_sales, SUM(r.mrp * r.shipping_quantity) AS mrp_ret, SUM(r.SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS r LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(r.phone, \'[^0-9]\', \'\'), 10) WHERE r.ORDER_STATUS = \'Processed\' AND r.category <> \'CARRY BAG\' GROUP BY 1, 2, 3 ), seg_net AS ( SELECT COALESCE(s.date, r.date) AS date, COALESCE(s.branch_code, r.branch_code) AS branch_code, COALESCE(s.seg, r.seg) AS seg, COALESCE(s.bills, 0) AS bills, COALESCE(s.gross_sales, 0) - COALESCE(r.ret_sales, 0) AS net_sales, COALESCE(s.mrp_gross, 0) - COALESCE(r.mrp_ret, 0) AS net_mrp, COALESCE(s.qty_gross, 0) - COALESCE(r.ret_qty, 0) AS net_qty, coalesce(s.gross_sales,0) as gross_sales, coalesce(r.ret_sales,0) as gross_returns FROM seg_sales s FULL OUTER JOIN seg_returns r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) AND r.seg = s.seg ), seg_daily AS ( SELECT date, branch_code, SUM(CASE WHEN seg = \'new\' THEN bills END) AS new_bills, SUM(CASE WHEN seg = \'new\' THEN net_sales END) AS new_sales, SUM(CASE WHEN seg = \'new\' THEN net_qty END) AS new_qty, SUM(CASE WHEN seg = \'new\' THEN net_mrp END) AS new_mrp, SUM(CASE WHEN seg = \'repeat\' THEN bills END) AS rpt_bills, SUM(CASE WHEN seg = \'repeat\' THEN net_sales END) AS rpt_sales, SUM(CASE WHEN seg = \'repeat\' THEN net_qty END) AS rpt_qty, SUM(CASE WHEN seg = \'repeat\' THEN net_mrp END) AS rpt_mrp FROM seg_net GROUP BY 1, 2 ), store_classification as ( select branch_code,location_simp,type_simp,city from snitch_db.maplemonk.offline_store_classification ) SELECT DATE_TRUNC(\'month\', e.date) AS month, e.date, e.branch_code, map.marketplace_mapped AS store_name, TRIM(SPLIT_PART(map.marketplace_mapped, \'-\', 2)) AS operating_model, UPPER(mo.STATE) AS STATE, mo.REGION, CASE WHEN UPPER(mo.PARTNER) IN (\'ABACUS AGENCIES INDIA PRIVATE LIMITED\') THEN \'ABACUS AGENCIES\' WHEN UPPER(mo.PARTNER) IN (\'KJ FASHION\') THEN \'KJ FASHION\' WHEN UPPER(mo.PARTNER) IN (\'SHIVERA LIFESTYLE\', \'SHIVERA LIFESTYLES PRIVATE LIMITED\') THEN \'DREAM SHIVERA PRIVATE LIMITED\' WHEN UPPER(mo.PARTNER) IN (\'SAPL\', \'SNITCH APPAREL PVT. LTD.\', \'SNITCH APPARELS PVT LTD\') THEN \'COCO\' ELSE UPPER(mo.PARTNER) END AS partner, UPPER(mo.AM) AS AM, mo.RM, mo.NSM, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' WHEN UPPER(mo.STATE) IN (\'ASSAM\',\'BIHAR\',\'CHHATTISGARH\',\'ODHISSA\',\'PUNJAB\',\'RAJASTHAN\',\'WEST BENGAL\') THEN \'ANISHA\' WHEN UPPER(mo.STATE) IN (\'KARNATAKA\') THEN \'PRIYANKA\' WHEN UPPER(mo.STATE) IN (\'MAHARASHTRA\') THEN \'RASHMI\' WHEN UPPER(mo.STATE) IN (\'NEW DELHI\',\'HARYANA\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'YUVRAJ\' WHEN UPPER(mo.STATE) IN (\'ANDHRA PRADESH\',\'TELANGANA\') THEN \'PREKSHYA\' WHEN UPPER(mo.STATE) IN (\'GUJARAT\',\'MADHYA PRADESH\') THEN \'APARNA\' WHEN UPPER(mo.STATE) IN (\'KERALA\',\'TAMIL NADU\') THEN \'P RAWAT\' ELSE \'UNKNOWN\' END AS MERCH_POC, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' ELSE \'FRESH\' END AS STORE_STATUS, UPPER(SC.CITY) AS CITY, sc.location_simp as CITY_TYPE, sc.type_simp as LOCATION_TYPE, t.target, e.net_sales AS sales, DIV0(e.net_sales, t.target) AS ach_pct, DIV0(e.net_sales - w.net_sales, w.net_sales) AS wow_growth_pct, t.mtd_target, e.mtd_sales, DIV0(e.mtd_sales, t.mtd_target) AS mtd_ach_pct, e.mtd_sales AS mtd_sales_net, e.bills, e.net_qty AS qty, e.multies, e.net_mrp AS mrp_sales, e.mtd_mrp AS mrp_sales_mtd, e.net_cogs AS cogs_sales, e.mtd_cogs AS cogs_sales_mtd, DIV0(e.net_mrp - e.net_sales, e.net_mrp) AS disc_pct, DIV0(e.mtd_mrp - e.mtd_sales, e.mtd_mrp) AS disc_pct_mtd, DIV0(e.net_qty, e.bills) AS upt_today, DIV0(e.mtd_qty, e.mtd_bills) AS upt_mtd, DIV0(e.net_sales, e.bills) AS atv_today, DIV0(e.mtd_sales, e.mtd_bills) AS atv_mtd, DIV0(e.net_sales, e.net_qty) AS asp, sg.new_sales AS new_sales, sg.rpt_sales AS repeat_sales, sg.new_bills AS new_bills, sg.rpt_bills AS repeat_bills, sg.new_qty AS new_qty, sg.rpt_qty AS repeat_qty, sg.new_mrp AS new_mrp, sg.rpt_mrp AS repeat_mrp, DIV0(sg.new_qty, sg.new_bills) AS new_upt, DIV0(sg.rpt_qty, sg.rpt_bills) AS repeat_upt, DIV0(sg.new_sales, sg.new_bills) AS new_aov, DIV0(sg.rpt_sales, sg.rpt_bills) AS repeat_aov, DIV0(sg.new_mrp - sg.new_sales, sg.new_mrp) AS new_disc_pct, DIV0(sg.rpt_mrp - sg.rpt_sales, sg.rpt_mrp) AS repeat_disc_pct, ly.mtd_sales AS l2l_sales_25, e.mtd_sales AS l2l_sales_26, DIV0(e.mtd_sales - ly.mtd_sales, ly.mtd_sales) AS l2l_growth_pct, e.omni_sales AS omni_sales, e.mtd_omni AS omni_sales_mtd, e.omni_sales_qty AS omni_sales_qty, e.mtd_omni_qty AS omni_sales_qty_mtd, e.walk_ins AS footfall_today, e.mtd_walkins AS footfall_mtd, DIV0(e.bills, e.walk_ins) AS conversion_today, DIV0(e.mtd_bills, e.mtd_walkins) AS conversion_mtd, DIV0(e.walk_ins - w.walk_ins, w.walk_ins) AS ff_growth_pct, iv.base_stock, iv.ideal_options, iv.total_inv AS inv_total, iv.apparel_inv AS inv_apparel, iv.fresh_inv AS inv_fresh, iv.total_options, iv.cut_options, iv.full_options, FROM enriched e LEFT JOIN mapping map ON LOWER(map.branch_code) = LOWER(e.branch_code) LEFT JOIN SNITCH_DB.MAPLEMONK.MASTER_OFFINE mo ON TRIM(e.branch_code) = TRIM(mo.\"BRANCH CODE\") LEFT JOIN targets t ON t.date = e.date AND LOWER(t.branch_code) = LOWER(e.branch_code) LEFT JOIN enriched w ON w.branch_code = e.branch_code AND w.date = DATEADD(\'day\', -7, e.date) LEFT JOIN enriched ly ON ly.branch_code = e.branch_code AND ly.yr = e.yr - 1 AND ly.mth = e.mth AND ly.dom = e.dom LEFT JOIN inv_metrics iv ON iv.date = e.date AND LOWER(iv.branch_code) = LOWER(e.branch_code) LEFT JOIN seg_daily sg ON sg.date = e.date AND LOWER(sg.branch_code) = LOWER(e.branch_code) LEFT JOIN store_classification sc on LOWER(sc.branch_code) = LOWER(e.branch_code) WHERE map.marketplace_mapped NOT LIKE \'%- WH -%\' and map.marketplace_mapped NOT IN (\'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - SNITCH X\',\'SNITCH - FOCO - MAPLE MYSURU\') ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.long_tail_dsr as WITH sales_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, SUM(selling_price) AS gross_sales, COUNT(DISTINCT ORDER_NAME) AS bills, SUM(SUBORDER_QUANTITY) AS qty, sum (case when sku_group like \'%4MSFR%\' then selling_price else null end ) as perf_sales, sum (case when sku_group like \'%4MTL0%\' then selling_price else null end ) as trolley_sales, sum (case when sku_group like \'SH%\' then selling_price else null end ) as shoes_sales, sum (case when sku_group like \'%4MSFR%\' then suborder_quantity else null end ) as perf_qty, sum (case when sku_group like \'%4MTL0%\' then suborder_quantity else null end ) as trolley_qty, sum (case when sku_group like \'SH%\' then suborder_quantity else null end ) as shoes_qty, COUNT(DISTINCT CASE WHEN sku_group like \'%4MSFR%\' then ORDER_NAME else null end) AS perf_bills, COUNT(DISTINCT CASE WHEN sku_group like \'SH%\' then ORDER_NAME else null end) AS shoes_bills, COUNT(DISTINCT CASE WHEN sku_group like \'%4MTL0%\' then ORDER_NAME else null end) AS trolley_bills, sum (case when sku_group like \'%4MSFR%\' and selling_price < 10 then suborder_quantity else null end ) as perf_free_qty, COUNT(DISTINCT CASE WHEN sku_group like \'%4MSFR%\' and selling_price < 10 then ORDER_NAME else null end) AS perf_free_bills, FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND sku_group NOT LIKE \'NT%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and order_date >= \'2026-09-01\' GROUP BY 1, 2 ), returns_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, SUM(selling_price) AS ret_sales, SUM(SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND SKU_GROUP NOT LIKE \'NT%\' and order_name not like \'RTO%\' and order_date >= \'2026-09-01\' GROUP BY 1, 2 ), multies_daily AS ( SELECT date, branch_code, COUNT(DISTINCT order_id) AS multies FROM ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, order_id, SUM(SHIPPING_QUANTITY) AS q FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE sku_group NOT LIKE \'CB%\' AND DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') and order_date >= \'2026-09-01\' GROUP BY 1, 2, 3 ) WHERE q >= 2 GROUP BY 1, 2 ), omni_daily AS ( SELECT DATE_TRUNC(\'day\', ORDER_DATE::DATE) AS date, branch_code, sum(shipping_quantity) as omni_sales_qty, SUM(selling_price) AS omni_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_STATUS = \'Processed\' AND sku_group NOT LIKE \'CB%\' AND DOC_PREFIX IN (\'OMS\') and order_date >= \'2026-09-01\' GROUP BY 1, 2 ), walkins_daily AS ( SELECT DATE_TRUNC(\'day\', order_date::DATE) AS date, round(code,0) AS branch_code, SUM(walk_ins) AS walk_ins FROM SNITCH_DB.MAPLEMONK.OFFLINE_WALKINS where order_date >= \'2026-09-01\' GROUP BY 1, 2 ), targets AS ( SELECT COALESCE(TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\')) AS date, TRIM(\"Branch \") AS branch_code, REPLACE(\"Target \", \',\', \'\')::INT AS target, REPLACE(\"MTD \", \',\', \'\')::INT AS mtd_target FROM SNITCH_DB.MAPLEMONK.MTD_TARGET where date >= \'2026-09-01\' ), mapping AS ( SELECT branch_code, marketplace_mapped FROM ( SELECT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY DATE_TRUNC(\'day\', ORDER_TIMESTAMP) DESC) AS rn FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE where order_date >= \'2026-09-01\' ) WHERE rn = 1 ), net_daily AS ( SELECT s.date, s.branch_code, YEAR(s.date) AS yr, MONTH(s.date) AS mth, DAY(s.date) AS dom, s.gross_sales - COALESCE(r.ret_sales, 0) AS net_sales, s.bills, s.qty - COALESCE(r.ret_qty, 0) AS net_qty, COALESCE(m.multies, 0) AS multies, COALESCE(o.omni_sales, 0) AS omni_sales, coalesce(o.omni_sales_qty,0) as omni_sales_qty, COALESCE(wk.walk_ins, 0) AS walk_ins, perf_sales, trolley_sales, shoes_sales, perf_qty, trolley_qty, shoes_qty, perf_bills, shoes_bills, trolley_bills, perf_free_qty, perf_free_bills, FROM sales_daily s LEFT JOIN returns_daily r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) LEFT JOIN multies_daily m ON m.date = s.date AND LOWER(m.branch_code) = LOWER(s.branch_code) LEFT JOIN omni_daily o ON o.date = s.date AND LOWER(o.branch_code) = LOWER(s.branch_code) LEFT JOIN walkins_daily wk ON wk.date = s.date AND LOWER(wk.branch_code) = LOWER(s.branch_code) ), enriched AS ( SELECT nd.*, SUM(net_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_sales, SUM(bills) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_bills, SUM(net_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_qty, SUM(omni_sales) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni, SUM(omni_sales_qty) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_omni_qty, SUM(walk_ins) OVER (PARTITION BY branch_code, yr, mth ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS mtd_walkins, FROM net_daily nd ), inv_raw AS ( SELECT date, branch_code, base_stock, cluster, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, fresh_inventory, new_category, COALESCE(NULLIF(dept_ideal, 0), 12) AS depth, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS, JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(sku_group) LIKE \'SH0%\' THEN CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN CASE WHEN ( (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END)) < 3 AND ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END)) < 4 THEN \'YES\' ELSE \'NO\' END WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE INVENTORY + JIT_QTY > 0 ), inv_bucketed AS ( SELECT date, branch_code, cluster, sku_group, closing_inventory, fresh_inventory, cut_size, new_category, base_stock, depth, CASE WHEN UPPER(new_category) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\',\'LUGGAGE\') THEN \'Long_Tail\' WHEN new_category IS NULL THEN NULL ELSE \'Apparel\' END AS category_bucket FROM inv_raw ), inv_agg AS ( SELECT date, branch_code, MAX(base_stock) AS base_stock, MAX(depth) AS depth, SUM(closing_inventory) AS total_inv, SUM(fresh_inventory) AS fresh_inv, SUM(CASE WHEN category_bucket = \'Apparel\' THEN closing_inventory END) AS apparel_inv, COUNT(DISTINCT CASE WHEN category_bucket = \'Apparel\' THEN sku_group END) AS total_options, COUNT(DISTINCT CASE WHEN cut_size = \'YES\' AND category_bucket = \'Apparel\' THEN sku_group END) AS cut_options, COUNT(DISTINCT CASE WHEN cut_size = \'NO\' AND category_bucket = \'Apparel\' THEN sku_group END) AS full_options FROM inv_bucketed WHERE category_bucket IS NOT NULL AND branch_code IS NOT NULL GROUP BY date, branch_code ), inv_metrics AS ( SELECT date, branch_code, COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ) AS base_stock, ROUND(DIV0( COALESCE( base_stock, FIRST_VALUE(base_stock) IGNORE NULLS OVER ( PARTITION BY branch_code ORDER BY date ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ), 0 ), depth )) AS ideal_options, COALESCE(total_inv, 0) AS total_inv, COALESCE(fresh_inv, 0) AS fresh_inv, COALESCE(apparel_inv, 0) AS apparel_inv, COALESCE(total_options, 0) AS total_options, COALESCE(cut_options, 0) AS cut_options, COALESCE(full_options, 0) AS full_options FROM inv_agg ), cust_first AS ( SELECT phone_no, MIN(first_order_date) AS first_order_date FROM SNITCH_DB.MAPLEMONK.CUSTOMER_ACQ_DATE_CHANNEL GROUP BY phone_no ), seg_sales AS ( SELECT DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) AS date, f.branch_code, CASE WHEN DATE_TRUNC(\'day\', f.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, COUNT(DISTINCT f.ORDER_NAME) AS bills, SUM(f.selling_price) AS gross_sales, SUM(f.mrp * f.shipping_quantity) AS mrp_gross, SUM(f.SUBORDER_QUANTITY) AS qty_gross FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE f LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) WHERE f.ORDER_STATUS = \'Processed\' AND f.sku_group NOT LIKE \'CB%\' AND f.sku_group NOT LIKE \'NT%\' AND f.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') GROUP BY 1, 2, 3 ), seg_returns AS ( SELECT DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) AS date, r.branch_code, CASE WHEN DATE_TRUNC(\'day\', r.ORDER_DATE::DATE) <= cf.first_order_date THEN \'new\' ELSE \'repeat\' END AS seg, SUM(r.selling_price) AS ret_sales, SUM(r.mrp * r.shipping_quantity) AS mrp_ret, SUM(r.SUBORDER_QUANTITY) AS ret_qty FROM SNITCH_DB.MAPLEMONK.STORE_RETURNS_FACT_ITEMS r LEFT JOIN cust_first cf ON cf.phone_no = \'+91\' || RIGHT(REGEXP_REPLACE(r.phone, \'[^0-9]\', \'\'), 10) WHERE r.ORDER_STATUS = \'Processed\' AND r.category <> \'CARRY BAG\' GROUP BY 1, 2, 3 ), seg_net AS ( SELECT COALESCE(s.date, r.date) AS date, COALESCE(s.branch_code, r.branch_code) AS branch_code, COALESCE(s.seg, r.seg) AS seg, COALESCE(s.bills, 0) AS bills, COALESCE(s.gross_sales, 0) - COALESCE(r.ret_sales, 0) AS net_sales, COALESCE(s.mrp_gross, 0) - COALESCE(r.mrp_ret, 0) AS net_mrp, COALESCE(s.qty_gross, 0) - COALESCE(r.ret_qty, 0) AS net_qty, coalesce(s.gross_sales,0) as gross_sales, coalesce(r.ret_sales,0) as gross_returns FROM seg_sales s FULL OUTER JOIN seg_returns r ON r.date = s.date AND LOWER(r.branch_code) = LOWER(s.branch_code) AND r.seg = s.seg ), seg_daily AS ( SELECT date, branch_code, SUM(CASE WHEN seg = \'new\' THEN bills END) AS new_bills, SUM(CASE WHEN seg = \'new\' THEN net_sales END) AS new_sales, SUM(CASE WHEN seg = \'new\' THEN net_qty END) AS new_qty, SUM(CASE WHEN seg = \'new\' THEN net_mrp END) AS new_mrp, SUM(CASE WHEN seg = \'repeat\' THEN bills END) AS rpt_bills, SUM(CASE WHEN seg = \'repeat\' THEN net_sales END) AS rpt_sales, SUM(CASE WHEN seg = \'repeat\' THEN net_qty END) AS rpt_qty, SUM(CASE WHEN seg = \'repeat\' THEN net_mrp END) AS rpt_mrp FROM seg_net GROUP BY 1, 2 ), store_classification as ( select branch_code,location_simp,type_simp,city from snitch_db.maplemonk.offline_store_classification ) SELECT DATE_TRUNC(\'month\', e.date) AS month, e.date, e.branch_code, map.marketplace_mapped AS store_name, TRIM(SPLIT_PART(map.marketplace_mapped, \'-\', 2)) AS operating_model, UPPER(mo.STATE) AS STATE, mo.REGION, CASE WHEN UPPER(mo.PARTNER) IN (\'ABACUS AGENCIES INDIA PRIVATE LIMITED\') THEN \'ABACUS AGENCIES\' WHEN UPPER(mo.PARTNER) IN (\'KJ FASHION\') THEN \'KJ FASHION\' WHEN UPPER(mo.PARTNER) IN (\'SHIVERA LIFESTYLE\', \'SHIVERA LIFESTYLES PRIVATE LIMITED\') THEN \'DREAM SHIVERA PRIVATE LIMITED\' WHEN UPPER(mo.PARTNER) IN (\'SAPL\', \'SNITCH APPAREL PVT. LTD.\', \'SNITCH APPARELS PVT LTD\') THEN \'COCO\' ELSE UPPER(mo.PARTNER) END AS partner, UPPER(mo.AM) AS AM, mo.RM, mo.NSM, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' WHEN UPPER(mo.STATE) IN (\'ASSAM\',\'BIHAR\',\'CHHATTISGARH\',\'ODHISSA\',\'PUNJAB\',\'RAJASTHAN\',\'WEST BENGAL\') THEN \'ANISHA\' WHEN UPPER(mo.STATE) IN (\'KARNATAKA\') THEN \'PRIYANKA\' WHEN UPPER(mo.STATE) IN (\'MAHARASHTRA\') THEN \'RASHMI\' WHEN UPPER(mo.STATE) IN (\'NEW DELHI\',\'HARYANA\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'YUVRAJ\' WHEN UPPER(mo.STATE) IN (\'ANDHRA PRADESH\',\'TELANGANA\') THEN \'PREKSHYA\' WHEN UPPER(mo.STATE) IN (\'GUJARAT\',\'MADHYA PRADESH\') THEN \'APARNA\' WHEN UPPER(mo.STATE) IN (\'KERALA\',\'TAMIL NADU\') THEN \'P RAWAT\' ELSE \'UNKNOWN\' END AS MERCH_POC, CASE WHEN E.BRANCH_CODE IN (\'104\',\'120\',\'123\',\'139\',\'146\',\'154\',\'155\',\'157\') THEN \'OUTLET\' ELSE \'FRESH\' END AS STORE_STATUS, UPPER(SC.CITY) AS CITY, sc.location_simp as CITY_TYPE, sc.type_simp as LOCATION_TYPE, t.target, e.net_sales AS sales, DIV0(e.net_sales, t.target) AS ach_pct, DIV0(e.net_sales - w.net_sales, w.net_sales) AS wow_growth_pct, t.mtd_target, e.mtd_sales, DIV0(e.mtd_sales, t.mtd_target) AS mtd_ach_pct, e.mtd_sales AS mtd_sales_net, e.bills, e.net_qty AS qty, e.multies, DIV0(e.net_qty, e.bills) AS upt_today, DIV0(e.mtd_qty, e.mtd_bills) AS upt_mtd, DIV0(e.net_sales, e.bills) AS atv_today, DIV0(e.mtd_sales, e.mtd_bills) AS atv_mtd, DIV0(e.net_sales, e.net_qty) AS asp, sg.new_sales AS new_sales, sg.rpt_sales AS repeat_sales, sg.new_bills AS new_bills, sg.rpt_bills AS repeat_bills, sg.new_qty AS new_qty, sg.rpt_qty AS repeat_qty, DIV0(sg.new_qty, sg.new_bills) AS new_upt, DIV0(sg.rpt_qty, sg.rpt_bills) AS repeat_upt, DIV0(sg.new_sales, sg.new_bills) AS new_aov, DIV0(sg.rpt_sales, sg.rpt_bills) AS repeat_aov, ly.mtd_sales AS l2l_sales_25, e.mtd_sales AS l2l_sales_26, DIV0(e.mtd_sales - ly.mtd_sales, ly.mtd_sales) AS l2l_growth_pct, e.omni_sales AS omni_sales, e.mtd_omni AS omni_sales_mtd, e.omni_sales_qty AS omni_sales_qty, e.mtd_omni_qty AS omni_sales_qty_mtd, e.walk_ins AS footfall_today, e.mtd_walkins AS footfall_mtd, DIV0(e.bills, e.walk_ins) AS conversion_today, DIV0(e.mtd_bills, e.mtd_walkins) AS conversion_mtd, DIV0(e.walk_ins - w.walk_ins, w.walk_ins) AS ff_growth_pct, iv.base_stock, e.perf_sales, e.trolley_sales, e.shoes_sales, e.perf_qty, e.trolley_qty, e.shoes_qty, e.perf_bills, e.shoes_bills, e.trolley_bills, e.perf_free_qty, e.perf_free_bills, FROM enriched e LEFT JOIN mapping map ON LOWER(map.branch_code) = LOWER(e.branch_code) LEFT JOIN SNITCH_DB.MAPLEMONK.MASTER_OFFINE mo ON TRIM(e.branch_code) = TRIM(mo.\"BRANCH CODE\") LEFT JOIN targets t ON t.date = e.date AND LOWER(t.branch_code) = LOWER(e.branch_code) LEFT JOIN enriched w ON w.branch_code = e.branch_code AND w.date = DATEADD(\'day\', -7, e.date) LEFT JOIN enriched ly ON ly.branch_code = e.branch_code AND ly.yr = e.yr - 1 AND ly.mth = e.mth AND ly.dom = e.dom LEFT JOIN inv_metrics iv ON iv.date = e.date AND LOWER(iv.branch_code) = LOWER(e.branch_code) LEFT JOIN seg_daily sg ON sg.date = e.date AND LOWER(sg.branch_code) = LOWER(e.branch_code) LEFT JOIN store_classification sc on LOWER(sc.branch_code) = LOWER(e.branch_code) WHERE map.marketplace_mapped NOT LIKE \'%- WH -%\' and map.marketplace_mapped NOT IN (\'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - SNITCH X\',\'SNITCH - FOCO - MAPLE MYSURU\') ; CREATE OR REPLACE TABLE snitch_db.maplemonk.customer_acq_date_channel_sku AS WITH perfume_orders AS ( SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'),10) AS phone_no, order_timestamp AS order_ts, order_timestamp::DATE AS order_date, UPPER(sku_group) AS sku_group, gross_sales AS sales, quantity AS quantity, combined_order_name::VARCHAR AS order_id, \'Online\' AS channel, \'Shopify\' AS store FROM snitch_db.maplemonk.fact_items_snitch WHERE UPPER(sku_group) LIKE \'%4MSFR%\' UNION ALL SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp AS order_ts, order_timestamp::DATE AS order_date, UPPER(sku_group) AS sku_group, selling_price AS sales, suborder_quantity AS quantity, order_name::VARCHAR AS order_id, \'Offline\' AS channel, marketplace_mapped AS store FROM snitch_db.maplemonk.store_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' AND UPPER(sku_group) LIKE \'%4MSFR%\' ), clean_orders AS ( SELECT * FROM perfume_orders WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\', \'+911234567891\', \'+910123456789\', \'+911111111111\', \'+912727272727\', \'+918888888888\', \'+919999999999\', \'+910000000000\', \'+912424242424\', \'+919909090909\' ) ), first_perfume_order AS ( SELECT phone_no, sku_group AS acq_sku_group, order_ts AS first_order_timestamp, order_date AS first_order_date, channel AS acq_channel, store AS acq_store FROM clean_orders QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_ts ASC, COALESCE(order_id, \'\') ASC, sku_group ASC ) = 1 ), customer_sales AS ( SELECT phone_no, SUM( CASE WHEN channel = \'Online\' THEN sales ELSE 0 END ) AS online_sales, SUM( CASE WHEN channel = \'Offline\' THEN sales ELSE 0 END ) AS offline_sales FROM clean_orders GROUP BY 1 ) SELECT a.phone_no, a.acq_sku_group AS sku_group, a.first_order_date, a.acq_store AS store, a.acq_channel, COALESCE(s.online_sales, 0) AS online_sales, COALESCE(s.offline_sales, 0) AS offline_sales, CASE WHEN COALESCE(s.online_sales, 0) >= COALESCE(s.offline_sales, 0) THEN \'Shopify\' ELSE \'Stores\' END AS customer_main_channel FROM first_perfume_order a LEFT JOIN customer_sales s ON a.phone_no = s.phone_no ;",
                    "transaction": true
                }
            ) }}
